// Shapes of the files in public/data, generated by data/scripts/06_build_app_data.mjs.
// Do not hand-edit public/data: change data/inputs/*.csv or the pipeline and rebuild.

export type RootDepth = 'shallow' | 'medium' | 'deep';

/** One crop from data/inputs/sowcast_crops.csv. Scores are 1 (low) to 5 (high). */
export interface Crop {
  id: string;
  name: string;
  family: string;
  season: string; // e.g. "wet season", "dry season", "perennial"
  role: string; // e.g. "main crop", "break crop", "cash crop", "green manure"
  water_need: number;
  nitrogen_fixing: boolean;
  root_depth: RootDepth;
  drought_tolerance: number;
  frost_tolerance: number;
  flood_tolerance: number;
  salinity_tolerance: number;
  sandy_soil_ok: number;
  temp_min_c: number;
  temp_max_c: number;
  season_days: number;
  seasonal_rain_need_mm: number;
  needs_flat_land: boolean;
  dry_season_crop: boolean;
  erosion_cover: number;
  organic_matter: number;
  market: number;
  forage_value: number;
  pest_notes: string;
  plain_description: string;
}

export interface RegionSummary {
  id: string;
  name: string; // e.g. "Central Dry Zone"
  place: string; // reference town, e.g. "Magway"
  country: string;
  lat: number;
  lon: number;
  tagline?: string;
  confidence: 'medium' | 'low'; // how well the team's draft region values are sourced
}

export interface MonthlyClimate {
  month: number; // 1-12
  tmax_c: number;
  tmin_c: number;
  precip_mm: number;
  et0_mm: number; // crop water demand (reference evapotranspiration)
  soil_moisture: number; // 0-1 soil wetness index (NASA POWER), not volumetric %
  ndvi: number | null; // 0-1 greenness; null until MODIS NDVI is fetched
  heat_days: number; // days ≥ 35 °C
  heavy_rain_days: number; // days ≥ 20 mm
  typically_bare: boolean | null; // null until NDVI is fetched
}

export interface AnnualClimate {
  year: number;
  heat_days: number;
  precip_mm: number;
  heavy_rain_days: number;
  max_dry_spell_days: number;
  water_balance_mm: number; // rain minus crop water demand
}

export interface TrendStat {
  per_decade: number | null;
  first_10y_mean: number | null;
  last_10y_mean: number | null;
  p: number | null; // Mann-Kendall p-value
}

export interface ClimateTrends {
  period: string; // e.g. "2001-2024"
  heat_days: TrendStat;
  precip_mm: TrendStat;
  heavy_rain_days: TrendStat;
  max_dry_spell_days: TrendStat;
  mean_water_balance_mm: number | null;
}

export interface SoilProfile {
  texture: string | null;
  organic_matter: string | null;
  drainage: string | null;
  water_holding: string | null;
  slope_pct: number | null;
  erosion_risk: string | null;
  sampled_km_from_town: number | null;
  source: string;
}

/** The team's draft region values (data/inputs/sowcast_regions.csv). Approximate, not measured. */
export interface RegionPriors {
  rain_mm: number;
  mean_temp_c: number;
  dry_months: number;
  soil_texture: string;
  drainage: string;
  slope_pct: number;
  flood_risk: number; // 0-3
  salinity_risk: number; // 0-3
  irrigation_access: number; // 0-3
  tree_crop_dominated: boolean;
  soil_degraded: boolean;
  common_crops: string[]; // crop ids
  evidence: string;
  confidence: 'medium' | 'low';
}

export interface PlainInsight {
  title: string;
  body: string;
  source: string;
  confidence: 'high' | 'medium' | 'experimental';
  badgeType?: 'warning' | 'opportunity' | 'neutral';
}

export interface RotationScores {
  soil: number; // 1-5
  water: number;
  erosion: number;
  income: number;
  pest_break: number;
}

export interface RotationOption {
  id: string; // current | alt_a | alt_b
  label: string; // "Current", "Option A", "Option B"
  name: string;
  tagline?: string;
  /** Steps in order. A step can combine crops grown together: "perennial_tree+cover_legume".
   *  Non-crop tokens: "fallow", "perennial_tree". */
  sequence: string[];
  cover_by_month: number[] | null; // null until crop calendars are collected
  scores: RotationScores;
  why: string;
  evidence: string[];
  benefits: string[];
  gaps: string[];
  risks: string[];
  confidence: 'medium' | 'low';
}

export interface CropFitResult {
  crop: string; // crop id
  rank: number;
  fit: number; // 0-95 rule-based score
  fit_band: 'high' | 'medium' | 'low';
  trend: 'increasing' | 'flat' | 'declining' | 'unknown';
  limits: string[];
  why: string[];
  common_locally: boolean;
  parts: { climate: number; water: number; soil: number; risk: number; benefit: number };
}

export interface RegionDetail {
  region: { id: string; name: string; place: string; country: string; lat: number; lon: number };
  monthly: MonthlyClimate[];
  annual: AnnualClimate[];
  trends: ClimateTrends;
  /** 'suspect' = the weather series has a break around 2008 here; weather numbers are hidden. */
  data_quality: {
    weather: 'ok' | 'suspect';
    note: string | null;
    sources: { rain: string | null; temperature: string | null; greenness: string | null; power_replaced: boolean };
  };
  /** Region inputs used by the crop scores: the team's draft value vs the measured one, and which was used. */
  scoring_inputs: { input: string; draft: string | number | null; measured: string | number | null; used: 'draft' | 'measured'; source: string }[];
  soil: SoilProfile | null;
  priors: RegionPriors;
  insights: PlainInsight[];
  rotations: RotationOption[];
  crop_fit: CropFitResult[];
  sources: string[];
}
